function finish(win){game.running=false;game.won=win;document.exitPointerLock?.();document.getElementById('endTitle').textContent=win?'Rift Sealed':'Lost to the Outworld';document.getElementById('endCopy').textContent=win?`The Ashen Reach is quiet — for now. You reached level ${game.player.level} and felled ${game.player.kills} creatures.`:'The rift swallows your light. Gather your strength and try again.';document.getElementById('endScreen').classList.remove('hide')}
function toggleInventory(){if(!game||!game.running)return;invOpen=!invOpen;document.getElementById('inventory').classList.toggle('open',invOpen);if(invOpen)document.exitPointerLock?.();else if(!('ontouchstart'in window))canvas.requestPointerLock?.();renderInventory()}
function renderInventory(){let list=document.getElementById('itemList');list.innerHTML='';let equipped=document.createElement('div');equipped.className='item';equipped.innerHTML=`<b>${game.player.weapon.name} ${game.player.weapon.rarity==='Common'?'(Equipped)':''}</b><small>ARC DAMAGE +${game.player.weapon.bonus}</small>`;list.appendChild(equipped);for(const [i,r] of game.relics.entries()){let el=document.createElement('div');el.className='item';el.innerHTML=`<b>${r.name}</b><small class="rarity">${r.rarity} • ARC DAMAGE +${r.bonus}</small>`;el.onclick=()=>{game.player.weapon=r;game.player.damage=24+r.bonus;game.player.weaponBonus=0;game.relics.splice(i,1);toast(`${r.name} EQUIPPED`);renderInventory()};list.appendChild(el)}if(!game.relics.length){let empty=document.createElement('div');empty.className='item';empty.innerHTML='<b>Nothing else found</b><small>Hunt the rift-spawn for relics.</small>';list.appendChild(empty)}}
function render(){if(!game)return;drawWorld();for(const q of game.shots){let a=spritePos({x:q.x2,y:q.y2}),b=spritePos({x:q.x1,y:q.y1});ctx.strokeStyle='#c0fff0';ctx.lineWidth=2;ctx.shadowColor='#65fff0';ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(b.x,H*.48);ctx.lineTo(a.x,H*.48);ctx.stroke();ctx.shadowBlur=0}if(game.player.invuln>0&&Math.floor(game.time*18)%2===0){ctx.fillStyle='#ff253522';ctx.fillRect(0,0,W,H)}}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;if(game&&game.running&&!invOpen)update(dt);if(game)render();requestAnimationFrame(frame)}
function start(){document.getElementById('startScreen').classList.add('hide');document.getElementById('hud').style.display='block';makeGame();updateHUD();if(!('ontouchstart'in window))canvas.requestPointerLock?.()}
document.getElementById('startBtn').addEventListener('click',start);document.getElementById('againBtn').addEventListener('click',()=>{document.getElementById('endScreen').classList.add('hide');start()});document.getElementById('closeInv').addEventListener('click',toggleInventory);
canvas.addEventListener('click',()=>{if(!game?.running)return;if(!('ontouchstart'in window)&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.();shoot()});canvas.addEventListener('mousemove',e=>{if(!game?.running||invOpen)return;if(document.pointerLockElement===canvas)game.player.a+=e.movementX*.0024;else if(e.buttons===1)game.player.a+=(e.movementX||0)*.006});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Digit1')nova();if(e.code==='Digit2')blink();if(e.code==='KeyQ')potion();if(e.code==='KeyI')toggleInventory();if(e.code==='Escape'&&invOpen)toggleInventory();if(e.code==='KeyE'&&game?.running&&dist(game.player,game.rift)<1.5&&game.rift.guardianDown){game.rift.active=false;finish(true)}if(e.code==='Space')shoot()});window.addEventListener('keyup',e=>keys[e.code]=false);
window.addEventListener('mousemove',e=>{if(game?.running&&!invOpen&&document.pointerLockElement===canvas)game.player.a+=e.movementX*.0024});
for(const el of document.querySelectorAll('[data-move]')){const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[el.dataset.move];el.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;el.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,()=>keys[code]=false)}
document.getElementById('touchShoot').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});document.getElementById('touchNova').addEventListener('pointerdown',e=>{e.preventDefault();nova()});
let touchLook=null;canvas.addEventListener('touchstart',e=>{if(!game?.running)return;touchLook=e.touches[0].clientX},{passive:true});canvas.addEventListener('touchmove',e=>{if(touchLook!==null){let x=e.touches[0].clientX;game.player.a+=(x-touchLook)*.008;touchLook=x}},{passive:true});canvas.addEventListener('touchend',()=>touchLook=null);
window.addEventListener('blur',()=>{keys={};mouse.down=false});
requestAnimationFrame(frame);
</script>
</body>
</html>

